-- because the supplied file ends part-way through that record.
-- The "Internal Notes" column is editorial and is deliberately not stored in this public repository;
-- it is filled in when the master file is imported through Team area → Food library.
-- ON CONFLICT DO NOTHING means this can never duplicate or overwrite a record.

VALUES ('UNBOXED_TOGETHER-INGREDIENT-DATABASE-v1 (initial import)', 'migration 018', 587, 1,
  '{"rejected": [{"ingredientId": "UIL-0591", "name": "Pregelatinised Starch", "reasons": ["Supplied file ends part-way through this record (fields after Source are missing)"]}], "missingFromFile": ["UIL-0107", "UIL-0109", "UIL-0112"]}'::jsonb);

ON CONFLICT (ingredient_id) DO NOTHING;

UPDATE ingredients SET import_batch_id = (SELECT MIN(id) FROM ingredient_import_batches) WHERE import_batch_id IS NULL;
