INSERT INTO ingredients (slug, ingredient_id, ingredient_name, alternative_names, ingredient_category, parent_ingredient, what_it_is, source, why_it_is_used, processing_level, main_nutritional_contribution, protein_relevance, fat_relevance, carbohydrate_sugar_relevance, fibre_relevance, blood_sugar_relevance, gut_relevance, inflammation_relevance, allergy_intolerance_concerns, who_should_be_aware, commonly_found_in, label_names, better_alternatives, vegan_status, vegetarian_status, gluten_relevance, nova_relevance, unboxed_classification, evidence_quality, regulatory_notes, unboxed_summary, scanner_matching_terms, common_misspellings, related_ingredients, related_additives, reference_sources, last_reviewed, extra_fields)
VALUES
  ('maltodextrin', 'UIL-0001', 'Maltodextrin', 'Corn maltodextrin; maize maltodextrin; tapioca maltodextrin; potato maltodextrin; rice maltodextrin', 'Refined carbohydrates', 'Starch', 'A rapidly digestible carbohydrate powder produced by partially breaking down starch.', 'Usually maize, potato, rice, wheat or tapioca starch.', 'Adds bulk; carries flavours; improves texture; helps powders dissolve; can replace some fat or sugar functionality.', 'Highly refined ingredient', 'Mostly carbohydrate; little fibre, protein, fat or micronutrient value.', 'Negligible', 'Negligible', 'High; rapidly digestible starch-derived carbohydrate.', 'Negligible', 'Can raise blood glucose quickly; the response depends on quantity and the full meal.', 'Usually absorbed in the small intestine; large amounts may cause digestive discomfort in some people.', 'No sound evidence that maltodextrin itself is inherently inflammatory in typical food amounts; overall dietary pattern matters.', 'Wheat-based maltodextrins are specifically exempt from mandatory Annex II allergen declaration in GB because of their processing. Other ingredient-specific sensitivities are not well established.', 'People monitoring blood glucose; people with diabetes; people with ingredient-specific sensitivities.', 'Sports powders; seasoning blends; sweets; soups; sauces; meal replacements; processed snacks.', 'Maltodextrin; maize maltodextrin; tapioca maltodextrin', 'Whole-food carbohydrate sources such as oats, potatoes, rice or fruit when practical.', 'Usually', 'Usually', 'Wheat-based maltodextrins are exempt from Annex II cereal-allergen declaration in GB. A separate gluten-free claim still depends on the finished food meeting applicable gluten thresholds.', 'Commonly used in NOVA 4 foods', 'Highly refined / formulation ingredient', 'Moderate', 'Wheat-based maltodextrins are specifically excluded from Annex II allergen declaration requirements in GB; ingredient labelling and any gluten-free claim remain separate requirements.', 'Maltodextrin is mainly a manufacturing carbohydrate. It can add a fast carbohydrate load without tasting especially sweet, so portion and product context matter.', 'maltodextrin|corn maltodextrin|maize maltodextrin|tapioca maltodextrin|potato maltodextrin|rice maltodextrin', 'maltodexrin; maltodextrine', 'Glucose syrup; dextrose; modified starch', 'None inherently; may appear alongside emulsifiers, sweeteners and flavourings', 'https://www.gov.uk/government/publications/food-allergen-labelling-and-information-requirements-technical-guidance/food-allergen-labelling-and-information-requirements-technical-guidance | https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('glucose-syrup', 'UIL-0002', 'Glucose Syrup', 'Corn syrup; glucose syrup solids; dried glucose syrup', 'Sugars and syrups', 'Starch', 'A concentrated syrup of glucose and related short-chain carbohydrates made by hydrolysing starch.', 'Commonly maize, wheat, potato or other food starch.', 'Sweetens; prevents crystallisation; adds body; retains moisture; controls texture.', 'Refined ingredient', 'Added carbohydrate and sugar-equivalent energy; little fibre or micronutrient value.', 'Negligible', 'Negligible', 'High; predominantly glucose-based carbohydrate.', 'Negligible', 'Generally raises blood glucose rapidly, depending on amount and the complete food.', 'Usually well absorbed; high intakes of sweet foods can contribute to gastrointestinal discomfort in some people.', 'No good evidence that glucose syrup uniquely causes inflammation; excess free-sugar intake and overall diet are more relevant.', 'Wheat-based glucose syrups are specifically exempt from mandatory Annex II allergen declaration in GB because of their processing. Individual intolerance is not an inherent property of glucose syrup.', 'People limiting free sugars; people monitoring blood glucose; people with diabetes.', 'Sweets; ice cream; cereal bars; bakery products; sauces; soft drinks; desserts.', 'Glucose syrup; corn syrup; glucose syrup solids; dried glucose syrup', 'Less-sweetened products; whole fruit; unsweetened foods.', 'Usually', 'Usually', 'Wheat-based glucose syrups are exempt from Annex II cereal-allergen declaration in GB. A gluten-free claim is a separate finished-product matter.', 'Context dependent', 'Refined added sugar', 'High', 'Wheat-based glucose syrups are specifically excluded from Annex II allergen declaration requirements in GB. As an added syrup, it contributes to free-sugar intake when used to sweeten foods.', 'Glucose syrup is an added, rapidly available carbohydrate used for both sweetness and texture. The main concern is cumulative free-sugar intake, not a unique toxic effect.', 'glucose syrup|corn syrup|glucose syrup solids|dried glucose syrup', 'glucose syrop; glucouse syrup', 'Dextrose; glucose-fructose syrup; invert sugar syrup', 'Sweeteners; flavourings', 'https://www.gov.uk/government/publications/food-allergen-labelling-and-information-requirements-technical-guidance/food-allergen-labelling-and-information-requirements-technical-guidance | https://www.nhs.uk/live-well/eat-well/food-types/how-does-sugar-in-our-diet-affect-our-health/ | https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('glucose-fructose-syrup', 'UIL-0003', 'Glucose-Fructose Syrup', 'Fructose-glucose syrup; isoglucose; high-fructose glucose syrup', 'Sugars and syrups', 'Starch', 'A starch-derived syrup containing both glucose and fructose. The name order generally reflects which sugar is present in the greater amount.', 'Usually maize or wheat starch.', 'Sweetens; retains moisture; improves texture; helps control crystallisation.', 'Highly refined ingredient', 'Added sugars and energy; little fibre, protein or micronutrient value.', 'Negligible', 'Negligible', 'High; mixture of glucose and fructose.', 'Negligible', 'Glucose contributes directly to blood glucose; total response depends on composition, amount and meal context.', 'Excess intake of fructose-containing sweeteners may cause symptoms in people with fructose malabsorption.', 'Evidence concerns high intake of added sugars overall; it is inaccurate to claim ordinary exposure uniquely causes inflammation.', 'No UK-regulated allergen is inherent to the syrup category itself, but manufacturing source and finished-product labelling should be checked. Fructose malabsorption is an intolerance issue rather than an allergy.', 'People limiting free sugars; people monitoring blood glucose; people with diagnosed fructose malabsorption who know fructose-containing syrups trigger symptoms.', 'Soft drinks; sweets; bakery products; yoghurts; sauces; desserts.', 'Glucose-fructose syrup; fructose-glucose syrup; isoglucose', 'Unsweetened products; whole fruit; products with lower total free sugar.', 'Usually', 'Usually', 'Source and processing dependent. Do not infer gluten status from the generic syrup name alone; use the finished-product allergen and gluten information.', 'Commonly used in NOVA 4 foods', 'Refined added sugar', 'Moderate', 'Permitted sweetening ingredient; should not be confused automatically with every formulation called HFCS in other markets.', 'This syrup combines glucose and fructose and is used for sweetness and manufacturing performance. Its relevance is mainly the amount of added sugar across the whole diet.', 'glucose-fructose syrup|fructose-glucose syrup|isoglucose|high fructose glucose syrup', 'glucose fructose syrop; fructose glucose syrop', 'Glucose syrup; invert sugar syrup; sucrose', 'Sweeteners; flavourings', 'https://www.nhs.uk/live-well/eat-well/food-types/how-does-sugar-in-our-diet-affect-our-health/ | https://www.gov.uk/government/publications/food-allergen-labelling-and-information-requirements-technical-guidance/food-allergen-labelling-and-information-requirements-technical-guidance | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('invert-sugar-syrup', 'UIL-0004', 'Invert Sugar Syrup', 'Inverted sugar syrup; invert syrup; invert sugar', 'Sugars and syrups', 'Sucrose', 'A syrup made by splitting sucrose into glucose and fructose.', 'Usually beet or cane sugar plus water and acid or enzymes.', 'Sweetens; retains moisture; reduces crystallisation; keeps products soft.', 'Refined ingredient', 'Added glucose and fructose; little fibre or micronutrient value.', 'Negligible', 'Negligible', 'High; free glucose and fructose.', 'Negligible', 'Can raise blood glucose; response depends on amount and the total food.', 'May trigger symptoms in some people with fructose malabsorption when consumed in sufficient quantities.', 'No evidence of a unique inflammatory effect apart from concerns related to excessive added-sugar intake.', 'No UK-regulated allergen is inherent to invert sugar syrup. Fructose malabsorption may be relevant for some people, depending on dose and individual tolerance.', 'People limiting free sugars; people monitoring blood glucose; people with diagnosed fructose malabsorption.', 'Fondants; confectionery; cakes; biscuits; jams; ice cream; cereal bars.', 'Invert sugar syrup; inverted sugar syrup; invert sugar', 'Less-sweetened foods; whole fruit; home-prepared alternatives.', 'Usually', 'Usually', 'Naturally gluten-free, but cross-contamination belongs to the product.', 'Context dependent', 'Refined added sugar', 'High', 'Permitted sugar ingredient.', 'Invert sugar is ordinary sucrose already split into glucose and fructose. It is useful to manufacturers because it stays smooth and moist, but nutritionally it remains added sugar.', 'invert sugar syrup|inverted sugar syrup|invert syrup|invert sugar', 'inverted syrop; invert syrop', 'Sucrose; glucose syrup; glucose-fructose syrup', 'None inherently', 'https://www.nhs.uk/live-well/eat-well/food-types/how-does-sugar-in-our-diet-affect-our-health/ | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('dextrose', 'UIL-0005', 'Dextrose', 'D-glucose; glucose monohydrate; anhydrous dextrose', 'Sugars and syrups', 'Glucose', 'A purified form of glucose, commonly produced from starch.', 'Usually maize or wheat starch; can be made from other starches.', 'Sweetens; supports browning; provides fermentable sugar; adds bulk; adjusts texture.', 'Refined ingredient', 'Rapidly available carbohydrate.', 'Negligible', 'Negligible', 'High; essentially glucose.', 'Negligible', 'Raises blood glucose quickly in most people.', 'Usually readily absorbed; high intakes can contribute to osmotic digestive symptoms.', 'No reliable evidence of a unique inflammatory effect; amount and overall sugar intake matter.', 'Wheat-based dextrose is specifically exempt from mandatory Annex II allergen declaration in GB because of its processing. The main general relevance is its glucose content rather than allergy.', 'People monitoring blood glucose; people with diabetes; people limiting added/free sugars.', 'Processed meats; baked goods; sports products; sweets; seasoning; fermentation products.', 'Dextrose; D-glucose; glucose monohydrate', 'Lower-sugar products; whole-food carbohydrate sources.', 'Usually', 'Usually', 'Wheat-based dextrose is exempt from Annex II cereal-allergen declaration in GB. A gluten-free claim remains a separate finished-product matter.', 'Context dependent', 'Refined added sugar', 'High', 'Permitted food ingredient.', 'Dextrose is glucose. It can be useful in fermentation and sports products, but in ordinary packaged foods it adds rapidly available carbohydrate with little else.', 'dextrose|d glucose|d-glucose|glucose monohydrate|anhydrous dextrose', 'dextrose powder; dextros', 'Glucose syrup; maltodextrin; sucrose', 'None inherently', 'https://www.gov.uk/government/publications/food-allergen-labelling-and-information-requirements-technical-guidance/food-allergen-labelling-and-information-requirements-technical-guidance | https://www.nhs.uk/live-well/eat-well/food-types/how-does-sugar-in-our-diet-affect-our-health/ | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('fruit-juice-concentrate', 'UIL-0006', 'Fruit Juice Concentrate', 'Concentrated fruit juice; fruit juice from concentrate; apple juice concentrate; grape juice concentrate', 'Fruit-derived sweeteners', 'Fruit juice', 'Fruit juice with much of its water removed. It may be reconstituted as juice or used as a sweetening ingredient.', 'Fruit, commonly apple, grape, pear or other juice.', 'Adds sweetness; fruit flavour; colour; acidity; solids.', 'Processed ingredient', 'Mostly sugars when used in small concentrated amounts; some acids and plant compounds vary by source.', 'Negligible', 'Negligible', 'Moderate to high; sugars are more concentrated and fibre is usually low.', 'Low unless pulp is retained.', 'Can raise blood glucose, especially when used primarily as a sweetener.', 'May cause symptoms in people sensitive to fructose or certain FODMAPs, depending on fruit and dose.', 'No basis for treating all concentrate as inflammatory; total free-sugar intake and the finished product matter.', 'Fruit-specific allergy is possible and depends on the fruit source. Fructose malabsorption may also be relevant for some people; this is an intolerance rather than an allergy.', 'People limiting free sugars; people with fruit-specific allergy; people with diagnosed fructose malabsorption; people interpreting products marketed as containing fruit.', 'Snack bars; yoghurts; drinks; sauces; baby foods; cereals; fruit snacks.', 'Fruit juice concentrate; apple juice concentrate; grape juice concentrate; pear juice concentrate', 'Whole fruit or products sweetened mainly with intact fruit.', 'Yes', 'Yes', 'Naturally gluten-free.', 'Context dependent', 'Concentrated fruit sugar source', 'Moderate', 'Fruit juice concentrates used in foods must be declared in the ingredients list as applicable. Sugars in fruit juices and similar concentrated juice ingredients count toward free sugars in UK dietary guidance.', 'Fruit concentrate begins as fruit, but removing water concentrates its sugars and removes much of the structure of whole fruit. In products it can function much like an added sweetener.', 'fruit juice concentrate|concentrated fruit juice|apple juice concentrate|grape juice concentrate|pear juice concentrate', 'fruit concentrate; juice concetrate', 'Fruit purée; fruit extract; glucose-fructose syrup', 'None inherently', 'https://www.nhs.uk/live-well/eat-well/food-types/how-does-sugar-in-our-diet-affect-our-health/ | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('modified-starch', 'UIL-0007', 'Modified Starch', 'Modified food starch; chemically modified starch; treated starch', 'Starches and thickeners', 'Starch', 'Starch altered physically, enzymatically or chemically to improve stability, thickening or processing performance.', 'Usually maize, potato, tapioca, rice or wheat starch.', 'Thickens; stabilises; improves freeze-thaw stability; controls texture; prevents separation.', 'Processed ingredient', 'Mostly carbohydrate; nutritional effect varies with the modification and amount.', 'Negligible', 'Negligible', 'Variable; many forms remain digestible, while some resistant starches behave differently.', 'Usually low, although resistant forms can contribute fibre-like properties.', 'Variable; cannot be assigned one universal effect.', 'Usually well tolerated; some products may cause discomfort depending on dose and individual sensitivity.', 'Insufficient evidence to label modified starch as inherently inflammatory.', 'Allergen relevance depends on the source. A wheat-derived modified starch that is not specifically exempt must identify the relevant cereal allergen in the finished food.', 'People with starch-specific sensitivities; people requiring strict allergen control; people monitoring highly formulated foods.', 'Sauces; soups; desserts; ready meals; bakery fillings; dairy alternatives.', 'Modified starch; modified food starch; treated starch', 'Traditional starches, reduction-based sauces, or simpler formulations where practical.', 'Usually', 'Usually', 'Source dependent. Wheat-derived starch ingredients require cereal-allergen consideration unless a specific legal exemption applies; gluten-free status belongs to the finished product.', 'Commonly used in NOVA 4 foods', 'Functional refined starch', 'Moderate', 'Some modified starches are authorised as additives and may carry E-numbers; others may be declared by functional name under applicable rules.', 'Modified starch is a family, not one substance. It is mainly used to make industrial foods stable and consistent, so the exact source and modification matter.', 'modified starch|modified food starch|treated starch|chemically modified starch', 'modifed starch; modified strach', 'Maize starch; tapioca starch; resistant starch', 'E1404; E1410; E1412; E1413; E1414; E1420; E1422; E1440; E1442; E1450; E1451', 'https://www.gov.uk/government/publications/food-allergen-labelling-and-information-requirements-technical-guidance/food-allergen-labelling-and-information-requirements-technical-guidance | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('maize-starch', 'UIL-0008', 'Maize Starch', 'Corn starch; cornflour (UK usage can vary); corn starch', 'Starches and thickeners', 'Maize', 'A fine starch separated from maize kernels.', 'Maize/corn grain.', 'Thickens sauces and fillings; lightens baking texture; prevents sticking.', 'Processed culinary ingredient', 'Mostly carbohydrate; little protein, fat or fibre.', 'Negligible', 'Negligible', 'High proportion of starch.', 'Low', 'Can raise blood glucose when eaten in substantial amounts; whole-meal context matters.', 'Usually well tolerated; large amounts of refined starch may be less satiating than intact grains.', 'No evidence that plain maize starch is inherently inflammatory.', 'Maize allergy can occur but maize is not one of the 14 UK-regulated allergens. Cross-contact is a finished-product manufacturing issue, not an inherent property of maize starch.', 'People with diagnosed maize allergy; people monitoring refined carbohydrate intake or blood glucose.', 'Sauces; custards; soups; gluten-free baking; confectionery.', 'Maize starch; corn starch; cornflour', 'Whole maize, oats, pulses or less-refined thickeners depending on the recipe.', 'Yes', 'Yes', 'Naturally gluten-free, but cross-contamination and product certification matter.', 'Context dependent', 'Refined culinary starch', 'High', 'Permitted conventional food ingredient.', 'Maize starch is a simple refined thickener. It is not automatically a problem, but it contains far less fibre and protein than the whole grain it came from.', 'maize starch|corn starch|cornstarch|cornflour', 'maze starch; corn flower', 'Modified starch; tapioca starch; potato starch', 'Modified starch additives when further treated', 'https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('rapeseed-oil', 'UIL-0009', 'Rapeseed Oil', 'Canola oil; refined rapeseed oil; cold-pressed rapeseed oil', 'Oils and fats', 'Rapeseed', 'Oil extracted from rapeseed. Composition and flavour differ between cold-pressed and refined versions.', 'Rapeseed seeds.', 'Cooking fat; carries flavour; adds moisture and texture; extends softness.', 'Processed culinary ingredient', 'Predominantly unsaturated fat, including omega-3 alpha-linolenic acid in variable amounts.', 'None', 'High; mostly mono- and polyunsaturated fats.', 'None', 'None', 'Little direct effect on blood glucose.', 'Usually well tolerated.', 'No good evidence supports labelling rapeseed oil as inherently inflammatory. UK guidance generally favours replacing saturated fats with unsaturated fats.', 'Rapeseed allergy is possible but uncommon. Refining substantially reduces residual protein; allergy risk can differ between refined and less-refined oils.', 'People with diagnosed rapeseed allergy; people managing total energy intake; people choosing oils based on fatty-acid profile or culinary use.', 'Cooking oils; mayonnaise; dressings; baked goods; ready meals; crisps.', 'Rapeseed oil; canola oil; cold-pressed rapeseed oil', 'Extra virgin olive oil for flavour; cold-pressed rapeseed oil where suitable; whole nuts and seeds for intact-food fats.', 'Yes', 'Yes', 'Naturally gluten-free.', 'Usually NOVA 2', 'Generally useful unsaturated culinary fat', 'High', 'Permitted edible oil; standard composition and labelling rules apply.', 'Rapeseed oil is mainly unsaturated fat. The meaningful distinction is often between a simple culinary use and its presence in a highly formulated product, not the oil alone.', 'rapeseed oil|canola oil|cold pressed rapeseed oil|refined rapeseed oil', 'rape seed oil; rapseed oil', 'Sunflower oil; olive oil; vegetable oil', 'Antioxidants may be added to some commercial oils', 'https://www.nhs.uk/live-well/eat-well/food-types/different-fats-nutrition/ | https://www.gov.uk/government/publications/sacn-statement-on-expressing-fat-and-carbohydrate-recommendations/sacn-statement-on-expressing-energy-fat-and-carbohydrate-intakes-and-recommendations | https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid', '2026-08-08', '{}'::jsonb),
  ('palm-oil', 'UIL-0010', 'Palm Oil', 'Palm fruit oil; palm olein; palm stearin', 'Oils and fats', 'Oil palm fruit', 'A semi-solid vegetable fat obtained from oil-palm fruit. Fractions such as palm olein and palm stearin have different melting properties.', 'Fruit of the oil palm.', 'Adds texture; improves shelf stability; provides solid fat without partial hydrogenation; supports frying.', 'Processed culinary ingredient', 'High fat; relatively high in saturated fat compared with many liquid vegetable oils.', 'None', 'High; substantial saturated fat content.', 'None', 'None', 'Little direct effect on blood glucose.', 'Usually well tolerated.', 'Do not classify palm oil as inherently inflammatory. Its main established nutritional distinction is its relatively high saturated-fat content compared with many liquid vegetable oils.', 'Allergic reactions to fully refined palm oil appear very rare; individual allergy cannot be ruled out completely. Saturated-fat content is a nutritional issue, not an allergy.', 'People limiting saturated fat; people managing total energy intake; people with a confirmed palm-related allergy.', 'Biscuits; spreads; confectionery; instant noodles; bakery products; frying fats.', 'Palm oil; palm fat; palm olein; palm stearin', 'Unsaturated oils such as rapeseed or olive oil where technically suitable; products using less solid fat.', 'Yes', 'Yes', 'Naturally gluten-free.', 'Context dependent', 'High-saturated-fat culinary ingredient', 'High', 'Permitted edible oil; sustainability certification is separate from nutrition regulation.', 'Palm oil is useful because it stays stable and semi-solid, but it contributes more saturated fat than many liquid oils. The whole product and portion remain important.', 'palm oil|palm fat|palm olein|palm stearin|palm fruit oil', 'palmoil; palm oill', 'Coconut oil; cocoa butter; vegetable fat', 'Antioxidants may be added', 'https://www.nhs.uk/live-well/eat-well/food-types/different-fats-nutrition/ | https://www.gov.uk/government/publications/sacn-statement-on-expressing-fat-and-carbohydrate-recommendations/sacn-statement-on-expressing-energy-fat-and-carbohydrate-intakes-and-recommendations | https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid', '2026-08-08', '{}'::jsonb),
  ('sunflower-oil', 'UIL-0011', 'Sunflower Oil', 'High-oleic sunflower oil; refined sunflower oil; cold-pressed sunflower oil', 'Oils and fats', 'Sunflower seed', 'Oil extracted from sunflower seeds; fatty-acid profile varies, especially between standard and high-oleic types.', 'Sunflower seeds.', 'Cooking; frying; carries flavours; adds moisture and texture.', 'Processed culinary ingredient', 'High fat; usually rich in unsaturated fats; omega-6 linoleic acid is common, while high-oleic types contain more monounsaturated fat.', 'None', 'High; mainly unsaturated fat.', 'None', 'None', 'Little direct effect on blood glucose.', 'Usually well tolerated.', 'Normal dietary use is not proven to be inherently inflammatory; claims that omega-6 automatically causes inflammation are oversimplified.', 'Sunflower seed allergy can occur. Allergy relevance of sunflower oil depends partly on refining because residual seed protein can vary; this is separate from its fatty-acid profile.', 'People with diagnosed sunflower seed allergy; people managing total energy intake; people selecting oils by fatty-acid profile.', 'Dressings; crisps; mayonnaise; bakery products; frying oils; spreads.', 'Sunflower oil; high-oleic sunflower oil; cold-pressed sunflower oil', 'Extra virgin olive oil; rapeseed oil; whole sunflower seeds depending on use.', 'Yes', 'Yes', 'Naturally gluten-free.', 'Usually NOVA 2', 'Generally useful unsaturated culinary fat', 'High', 'Permitted edible oil.', 'Sunflower oil is mostly unsaturated fat, but its exact profile depends on the variety. It should be judged by type, cooking use and the food around it rather than by a blanket ''seed oil'' label.', 'sunflower oil|high oleic sunflower oil|cold pressed sunflower oil|refined sunflower oil', 'sun flower oil; sunflower oill', 'Rapeseed oil; safflower oil; vegetable oil', 'Antioxidants may be added', 'https://www.nhs.uk/live-well/eat-well/food-types/different-fats-nutrition/ | https://www.gov.uk/government/publications/sacn-statement-on-expressing-fat-and-carbohydrate-recommendations/sacn-statement-on-expressing-energy-fat-and-carbohydrate-intakes-and-recommendations | https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid', '2026-08-08', '{}'::jsonb),
  ('extra-virgin-olive-oil', 'UIL-0012', 'Extra Virgin Olive Oil', 'EVOO; cold-extracted olive oil; virgin olive oil', 'Oils and fats', 'Olive fruit', 'The highest grade of olive oil, obtained mechanically without refining and meeting chemical and sensory standards.', 'Olive fruit.', 'Cooking; dressings; flavour; carries fat-soluble compounds.', 'Processed culinary ingredient', 'Mostly monounsaturated fat plus variable polyphenols and vitamin E.', 'None', 'High; mainly monounsaturated fat.', 'None', 'None', 'Little direct effect on blood glucose; can slow gastric emptying as part of a mixed meal.', 'Usually well tolerated.', 'Evidence around olive oil is generally favourable within healthy dietary patterns, but effects should not be attributed to a single ingredient in isolation or presented as treatment.', 'Olive allergy is possible but uncommon. Most people tolerate extra virgin olive oil; individual reactions require product-specific assessment.', 'People with confirmed olive allergy; people managing total energy intake; consumers comparing olive-oil grades and authenticity.', 'Dressings; marinades; cooking; dips; Mediterranean-style dishes.', 'Extra virgin olive oil; EVOO; cold-extracted olive oil', 'No direct replacement needed; whole olives, nuts and seeds can add intact-food fats.', 'Yes', 'Yes', 'Naturally gluten-free.', 'Usually NOVA 2', 'Minimally refined unsaturated culinary fat', 'High', 'Subject to olive-oil composition, grade and marketing standards.', 'Extra virgin olive oil is a minimally refined fat with a strong evidence base within healthy dietary patterns. Quality, storage and quantity still matter.', 'extra virgin olive oil|evoo|cold extracted olive oil|virgin olive oil', 'extra virgin oilive oil; olive oill', 'Virgin olive oil; refined olive oil; olives', 'None inherently', 'https://www.nhs.uk/live-well/eat-well/food-types/different-fats-nutrition/ | https://www.gov.uk/government/publications/composition-of-foods-integrated-dataset-cofid | https://www.gov.uk/food-labelling-and-packaging/ingredients-list', '2026-08-08', '{}'::jsonb),
  ('whey-protein-concentrate', 'UIL-0013', 'Whey Protein Concentrate', 'WPC; whey concentrate; milk whey protein concentrate', 'Protein ingredients', 'Milk whey', 'A protein-rich powder made by filtering and drying the liquid whey left from cheese production. Protein percentage varies by grade.', 'Cow''s milk whey, commonly.', 'Raises protein content; improves texture; water binding; foaming; browning.', 'Processed ingredient', 'High-quality complete protein; may retain some lactose and fat.', 'High; contains all essential amino acids and is rich in leucine.', 'Low to moderate depending on grade.', 'Low; may contain residual lactose.', 'Negligible', 'Usually low direct effect; flavoured products may contain added sugars.', 'May cause symptoms in lactose-intolerant people depending on residual lactose; milk protein can trigger allergy.', 'Not established as inherently inflammatory; milk allergy is an immune reaction and is distinct from intolerance.', 'Contains milk protein and must be avoided by people with milk allergy. Residual lactose varies by concentrate grade, so tolerance in lactose intolerance is product dependent.', 'People with milk allergy; people with lactose intolerance; people advised to modify protein intake for a medical condition.', 'Protein powders; bars; sports foods; bakery products; meal replacements; yoghurt products.', 'Whey protein concentrate; WPC; whey concentrate', 'Whole dairy foods, eggs, fish, meat, tofu or pulses depending on dietary needs.', 'No', 'Check manufacturer', 'Naturally gluten-free, but product contamination matters.', 'Commonly used in NOVA 4 foods', 'Concentrated complete protein', 'High', 'Milk allergen must be clearly declared in the UK.', 'Whey concentrate is a useful complete protein, but it is still an isolated ingredient and may contain lactose. The finished product matters more than the protein claim on the front.', 'whey protein concentrate|wpc|whey concentrate|milk whey protein concentrate', 'way protein concentrate; whey protien concentrate', 'Whey protein isolate; milk protein concentrate; casein', 'Flavourings; sweeteners; emulsifiers often accompany it', 'https://www.gov.uk/government/publications/food-allergen-labelling-and-information-requirements-technical-guidance/food-allergen-labelling-and-information-requirements-technical-guidance | https://pubmed.ncbi.nlm.nih.gov/25757896/', '2026-08-08', '{}'::jsonb),
  ('whey-protein-isolate', 'UIL-0014', 'Whey Protein Isolate', 'WPI; whey isolate; isolated whey protein', 'Protein ingredients', 'Milk whey', 'A more highly filtered whey powder containing a higher proportion of protein and usually less lactose and fat than concentrate.', 'Cow''s milk whey, commonly.', 'Raises protein with limited carbohydrate and fat; improves texture and solubility.', 'Processed ingredient', 'Very high-quality complete protein; usually low lactose and fat.', 'Very high; complete essential amino-acid profile and rich in leucine.', 'Low', 'Low, but not necessarily zero lactose.', 'Negligible', 'Usually low direct effect unless the product contains added carbohydrate.', 'Often better tolerated than concentrate by some lactose-intolerant people, but unsuitable for milk allergy.', 'Not established as inherently inflammatory; allergy concerns are separate.', 'Contains milk protein and is unsuitable for people with milk allergy. Lactose is usually lower than in whey concentrate but is not guaranteed absent unless specifically tested or labelled.', 'People with milk allergy; people with lactose intolerance who need to check residual lactose; people advised to modify protein intake for a medical condition.', 'Protein powders; clear protein drinks; bars; fortified foods.', 'Whey protein isolate; WPI; isolated whey protein', 'Whole-food proteins; whey concentrate where tolerated and appropriate; plant proteins for vegan diets.', 'No', 'Check manufacturer', 'Naturally gluten-free, but check the final product.', 'Commonly used in NOVA 4 foods', 'Highly isolated complete protein', 'High', 'Milk allergen must be declared.', 'Whey isolate delivers concentrated complete protein with little lactose or fat. It can be useful, but a high-protein label does not automatically make the overall product nutritious.', 'whey protein isolate|wpi|whey isolate|isolated whey protein', 'way protein isolate; whey protien isolate', 'Whey concentrate; milk protein isolate; casein',